import { LESSONS } from './coachLessons.js';

// Original applications, not recalled examination items. Each option has its own
// reason. No copied commercial bank or private source document is redistributed.
function question(id, lessonId, prompt, correct, distractors, mechanism, source) {
  const lesson = LESSONS.find(l => l.id === lessonId);
  const pairs = [correct, ...distractors];
  return { id: `expand-${id}`, lessonId, category: lesson.category, topic: lesson.title,
    q: prompt, options: pairs.map(p => p[0]), answer: 0,
    explanation: `${correct[1]} ${mechanism}`,
    rationales: pairs.map((p, i) => `${i === 0 ? 'Correct: ' : ''}${p[1]}`),
    steps: [], source: source || lesson.source, section: lesson.outline };
}
